WITH expected AS (SELECT value AS e FROM jsonb_array_elements($triggers$[{"name":"sync_feed_delete","table":"audit_logs","definition":"CREATE TRIGGER sync_feed_delete AFTER DELETE ON public.audit_logs REFERENCING OLD TABLE AS old_audit_rows FOR EACH STATEMENT EXECUTE FUNCTION sync_feed_audit_logs_delete()","body_md5":"c232143d97ad08ea5c63d6ac7dc2a904"},{"name":"sync_feed_insert","table":"audit_logs","definition":"CREATE TRIGGER sync_feed_insert AFTER INSERT ON public.audit_logs REFERENCING NEW TABLE AS new_audit_rows FOR EACH STATEMENT EXECUTE FUNCTION sync_feed_audit_logs_insert()","body_md5":"2ed8a858c85562e2c8f3cbeb0b24c3fe"},{"name":"sync_feed_update","table":"audit_logs","definition":"CREATE TRIGGER sync_feed_update AFTER UPDATE ON public.audit_logs REFERENCING NEW TABLE AS new_audit_rows FOR EACH STATEMENT EXECUTE FUNCTION sync_feed_audit_logs_update()","body_md5":"72f36486de2ae53fe755ddce16151ab0"},{"name":"shifts_aa_stale_guard","table":"shifts","definition":"CREATE TRIGGER shifts_aa_stale_guard BEFORE UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION skip_stale_update()","body_md5":"3733e4ac528c834bfd20f8764a466f03"},{"name":"shifts_bump_row_version","table":"shifts","definition":"CREATE TRIGGER shifts_bump_row_version BEFORE UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION bump_row_version()","body_md5":"590b3078ce355a216f389c60b8008d8d"},{"name":"shifts_guard_client_writes","table":"shifts","definition":"CREATE TRIGGER shifts_guard_client_writes BEFORE INSERT OR UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION shifts_guard_client_writes()","body_md5":"ebe71ffe053a6f6f397b3a53c2e8e566"},{"name":"shifts_set_updated_at","table":"shifts","definition":"CREATE TRIGGER shifts_set_updated_at BEFORE UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()","body_md5":"749d6e72e457701152e365704cde3807"},{"name":"shifts_sync_status_trg","table":"shifts","definition":"CREATE TRIGGER shifts_sync_status_trg BEFORE INSERT OR UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION shifts_sync_status()","body_md5":"45652b7ffe1794ac619f32e0a9e5cb81"},{"name":"shifts_unfinished_tickets","table":"shifts","definition":"CREATE TRIGGER shifts_unfinished_tickets BEFORE UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION guard_shift_unfinished_tickets()","body_md5":"1539979362f3d8509800d00a44709ba1"},{"name":"sync_feed_change","table":"shifts","definition":"CREATE TRIGGER sync_feed_change AFTER INSERT OR DELETE OR UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION sync_feed_shifts()","body_md5":"a0a9de529599da6ce8b86c41f07a9d51"}]$triggers$::jsonb))
SELECT e->>'table' AS table_name,e->>'name' AS trigger_name,
 t.oid IS NOT NULL AS exists,t.tgenabled='O' AS enabled_origin,
 pg_get_triggerdef(t.oid)=e->>'definition' AS exact_definition,
 md5(p.prosrc)=e->>'body_md5' AS exact_raw_body,
 md5(p.prosrc) AS current_raw_md5,e->>'body_md5' AS pinned_raw_md5,
 (SELECT count(*) FROM pg_trigger x WHERE x.tgrelid IN('public.shifts'::regclass,'public.audit_logs'::regclass) AND NOT x.tgisinternal)=10 AS exact_trigger_count
FROM expected
LEFT JOIN pg_trigger t ON t.tgrelid=('public.'||(e->>'table'))::regclass AND t.tgname=e->>'name' AND NOT t.tgisinternal
LEFT JOIN pg_proc p ON p.oid=t.tgfoid
ORDER BY e->>'table',e->>'name';
